@app.cell
def _(is_script_mode, mo, run_search, search_form):
    SAMPLE_QUERIES = [
        "how does dbt transform data in the warehouse",
        "distributed SQL database replication",
        "YugabyteDB",
        "what is a B-tree index",
        "how does query optimization work",
    ]

    if is_script_mode:
