    elif search_form.value is not None:
        form_values = search_form.value
        jobs = [
            (
                form_values["query"],
                int(form_values["top_k"]),
                float(form_values["fts_weight"]),
            )
        ]
    else:
        jobs = []

    all_results = [
        (query, fts_weight, run_search(query, top_k, fts_weight))
